import { Formik, Form, Field, ErrorMessage } from "formik";
import { object, string } from "yup";
import axios from "axios";
import { useState } from "react";
import { useNavigate } from "react-router-dom";
import ROUTES from "../../Routes";

import "./SignIn.css";

const SignIn = () => {
  const [user, setUser] = useState([]);

  const InitialValues = { userName: "", pass: "" };

  const validationSchema = object({
    userName: string(),
    // .matches(
    //   /^[a-zA-Z0-9](?:[a-zA-Z0-9_-]{1,14}[a-zA-Z0-9])?$/,
    //   "Username must be 3–16 characters long, can include letters, numbers, underscores (_), and hyphens (-), but cannot start or end with a symbol."
    // ),
    pass: string(),
    // .matches(
    //   /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*])[A-Za-z\d!@#$%^&*]{8,20}$/,
    //   "Password must be 8–20 characters long and include at least one uppercase letter, one lowercase letter, one number, and one special character (!@#$%^&*). Spaces are not allowed."
    // ),
  });

  const navigate = useNavigate();

  const checkUserName = (e) => {
    axios("http://localhost:3001/users").then((res) => setUser(res.data));
//     const exist = user.some((item)=> item.username === e.userName && item.password === e.pass)
// exist?navigate(`/${ROUTES.USERS}/${item.firstName}`)
    user.map((item) => {
      if (item.username === e.userName && item.password === e.pass) {
         navigate(`/${ROUTES.USERS}/${item.id}`);
        //  console.log(item.id);

      }
    });
  };

  return (
    <div className="mainSignIn">
      <p>Page does not exist</p>
      <Formik
        initialValues={InitialValues}
        validationSchema={validationSchema}
        onSubmit={(e) => checkUserName(e)}
      >
        <Form className="form">
          <Field
            placeholder="Username"
            name="userName"
            className="field"
          ></Field>
          <ErrorMessage component="p" name="userName"></ErrorMessage>
          <Field
            placeholder="Password"
            name="pass"
            type="password"
            className="field"
          ></Field>
          <ErrorMessage component="p" name="pass"></ErrorMessage>
          <button type="submit" className="btn">
            Log in
          </button>
        </Form>
      </Formik>
      <div className="divSign">
        <p>Don't have an account?</p>
        <button className="btn">Sign up</button>
      </div>
    </div>
  );
};

export default SignIn;
